<div class="ac-callout">Product approval is separate from sustainability-claim or certificate verification. Only clean-scanned images can accompany an approved product.</div>
<div id="admin-catalog-message" class="ac-callout mt-3" role="status" hidden></div>
<section class="ac-card mt-3"><div class="ac-head"><h2>Product review queue</h2><div class="ac-actions"><select id="admin-catalog-status" class="ac-select" aria-label="Filter review status"><option value="pending_review">Pending review</option><option value="under_review">Under review</option><option value="changes_requested">Changes requested</option><option value="rejected">Rejected</option><option value="approved">Approved</option><option value="">All products</option></select><button id="admin-catalog-refresh" type="button" class="ac-btn small">Refresh</button></div></div><div class="ac-body" id="admin-catalog-list">Loading products…</div></section>
<section class="ac-card mt-3" id="admin-catalog-detail" hidden><div class="ac-head"><h2 id="admin-catalog-name">Product review</h2><span class="ac-status" id="admin-catalog-state"></span></div><div class="ac-body"><div class="ac-form-grid"><div><h3>Submitted details</h3><div id="admin-catalog-summary"></div></div><div><h3>Images and scan status</h3><div id="admin-catalog-images"></div></div></div><div class="ac-field mt-3"><label for="admin-catalog-notes">Vendor-visible review note</label><textarea class="ac-textarea" id="admin-catalog-notes" minlength="10" maxlength="1000" placeholder="Describe the decision and required corrections precisely."></textarea></div><div class="ac-form-actions" id="admin-catalog-actions"></div></div></section>
